package dev.shadock.shadock.ui;

import dev.shadock.shadock.Shadock;
import net.minecraft.client.gui.components.AbstractSelectionList;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.resources.Identifier;

// Our art is 2x resolution, generated by tools/make_assets.py. The list background and separators
// stay vanilla so they follow whatever resource pack the player runs.
public final class DockSprites {
	// Vanilla (resource-pack aware)
	public static final Identifier LIST_BACKGROUND = AbstractSelectionList.INWORLD_MENU_LIST_BACKGROUND;
	public static final Identifier HEADER_SEPARATOR = Screen.INWORLD_HEADER_SEPARATOR;
	public static final Identifier FOOTER_SEPARATOR = Screen.INWORLD_FOOTER_SEPARATOR;

	// Chrome (nine-slice)
	public static final Identifier PANEL = own("panel");
	public static final Identifier BUTTON = own("button_normal");
	public static final Identifier BUTTON_HIGHLIGHTED = own("button_highlighted");
	public static final Identifier BUTTON_PRESSED = own("button_pressed");
	public static final Identifier BUTTON_DISABLED = own("button_disabled");
	public static final Identifier SCROLLER = own("scroller");
	public static final Identifier SCROLLER_BACKGROUND = own("scroller_background");

	// Branding
	public static final Identifier LOGO = own("logo");
	// texture is 4x; drawn at about 63x10
	public static final Identifier WORDMARK = own("wordmark");
	public static final int WORDMARK_WIDTH = 63;
	public static final int WORDMARK_HEIGHT = 10;

	// Toolbar icons (drawn at 12x12)
	public static final Identifier CLOSE = own("close");
	public static final Identifier IMPORT = own("import");
	public static final Identifier FOLDER = own("folder");
	public static final Identifier SORT_CUSTOM = own("sort_custom");
	public static final Identifier SORT_ALPHA = own("sort_alpha");
	public static final Identifier KEY = own("key");
	public static final Identifier SETTINGS = own("settings");

	// Row icons (drawn at 8x8; the checkmark at 9x8)
	public static final Identifier ROW_ZIP = own("zip");
	public static final Identifier ROW_FOLDER = own("pack_folder");
	public static final Identifier ROW_INVALID = own("invalid");
	public static final Identifier ROW_GRIP = own("grip");
	public static final Identifier ROW_LOCK = own("lock");
	public static final Identifier CHECKMARK = own("check");
	public static final Identifier SPINNER = own("spinner");

	private DockSprites() {
	}

	private static Identifier own(String path) {
		return Identifier.fromNamespaceAndPath(Shadock.MOD_ID, path);
	}
}
